output_text:
[
  {
    "id": "return_cart_to_top_left_bay",
    "text": "A shopper who enters the store is obliged to return the cart to the top-left cart-return bay before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "top_left_cart_return_bay": "at(0,1)",
        "cart_returned_to_bay": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "top_left_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_without_returned_cart",
    "text": "It is forbidden to exit unless the cart has already been parked at the designated top-left return bay.",
    "abstraction": {
      "state_properties": {
        "cart_is_parked_at_return_bay": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_is_parked_at_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "only_leave_cart_at_return_bay",
    "text": "A shopper may put a cart down only at the designated cart-return cell.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_cell": "at(0,1)"
      },
      "events": {
        "leave_cart_somewhere": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_somewhere",
          {
            "not": "designated_cart_return_cell"
          }
        ]
      }
    }
  },
  {
    "id": "borrowed_cart_must_be_returned",
    "text": "Once a shopper takes the store cart from its start station, they are obliged to return that cart to the top-left bay.",
    "abstraction": {
      "state_properties": {
        "start_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "top_left_cart_return_bay": "at(0,1)",
        "cart_returned_to_bay": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "take_store_cart": {
          "pre": {
            "and": [
              "start_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_store_cart": {
          "pre": {
            "and": [
              "top_left_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_store_cart",
      "discharge": "return_store_cart"
    }
  },
  {
    "id": "must_take_cart_before_shopping",
    "text": "Before doing any shopping, the agent is obliged to take the available cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "items_only_into_cart",
    "text": "It is forbidden to pick up shelf items unless the shopper is currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_shelf_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "take_shelf_item",
          {
            "not": "pushing_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Social etiquette forbids carrying groceries by hand; items should be transported in the cart instead.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "no_cart_in_exit_approach",
    "text": "Carts are forbidden in the front exit approach area, so shoppers must leave the cart before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "front_exit_approach": {
          "or": [
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "front_exit_approach",
          "pushing_cart"
        ]
      }
    }
  }
]
